(() => {
    'use strict';

    // Tavern Helper runs global scripts inside a same-origin iframe.
    const host = window.parent;
    const doc = host.document;
    const root = doc.documentElement;
    const runtimeKey = '__screenOtherSideLauncher';
    const marker = 'data-screen-launcher';
    const commands = [
        ['ai-config-button', '预设', 'config'],
        ['sys-settings-button', 'API', 'api'],
        ['advanced-formatting-button', '格式', 'format'],
        ['WI-SP-button', '世界书', 'worldbook'],
        ['user-settings-button', '用户设置', 'settings'],
        ['backgrounds-button', '背景', 'wallpaper'],
        ['extensions-settings-button', '扩展', 'extensions'],
        ['persona-management-button', '身份', 'persona'],
        ['rightNavHolder', '角色', 'characters'],
    ];

    function nativeControl(id) {
        const drawer = doc.getElementById(id);
        return drawer?.querySelector(':scope > .drawer-toggle .drawer-icon')
            ?? drawer?.querySelector(':scope > .drawer-toggle')
            ?? null;
    }

    host[runtimeKey]?.destroy();

    let view;
    const listeners = new host.AbortController();
    const on = { signal: listeners.signal };

    function close(restoreFocus = false) {
        if (!view || view.grid.hidden) return;
        view.grid.hidden = true;
        view.toggle.setAttribute('aria-expanded', 'false');
        view.toggle.setAttribute('aria-label', '展开酒馆菜单');
        if (restoreFocus) view.toggle.focus({ preventScroll: true });
    }

    function unmount() {
        root.removeAttribute(marker);
        view?.shell.remove();
        view = undefined;
    }

    function mount() {
        const shell = doc.createElement('nav');
        shell.id = 'screen-other-side-nav';
        shell.setAttribute('aria-label', '酒馆菜单');

        const toggle = doc.createElement('button');
        toggle.id = 'screen-other-side-toggle';
        toggle.type = 'button';
        toggle.setAttribute('aria-expanded', 'false');
        toggle.setAttribute('aria-controls', 'screen-other-side-grid');
        toggle.setAttribute('aria-label', '展开酒馆菜单');

        const grid = doc.createElement('div');
        grid.id = 'screen-other-side-grid';
        grid.hidden = true;

        for (const [id, name, icon] of commands) {
            const item = doc.createElement('button');
            item.type = 'button';
            item.dataset.screenIcon = icon;
            item.className = 'screen-other-side-item';
            item.textContent = name;
            item.onclick = () => {
                const control = nativeControl(id);
                close();
                if (control) control.click();
                else unmount();
            };
            grid.append(item);
        }

        toggle.onclick = event => {
            if (!grid.hidden) {
                close(true);
                return;
            }
            grid.hidden = false;
            toggle.setAttribute('aria-expanded', 'true');
            toggle.setAttribute('aria-label', '收起酒馆菜单');
            // Leave touch activation at the launcher; expose the grid in tab order.
            if (event.detail === 0) grid.firstElementChild?.focus({ preventScroll: true });
        };
        shell.append(toggle, grid);
        doc.body.append(shell);
        view = { shell, toggle, grid };
        root.setAttribute(marker, '');
    }

    function sync() {
        const selected = host.getComputedStyle(root).getPropertyValue('--screen-other-side-enabled').trim() === '1';
        const ready = selected && doc.body && commands.every(([id]) => nativeControl(id));
        if (!ready) {
            if (view) unmount();
            return;
        }
        if (!view?.shell.isConnected) mount();
    }

    doc.addEventListener('pointerdown', event => {
        if (view && !view.shell.contains(event.target)) close();
    }, { ...on, capture: true });
    doc.addEventListener('keydown', event => {
        if (event.key === 'Escape' && view && !view.grid.hidden) {
            event.preventDefault();
            event.stopPropagation();
            close(true);
        }
    }, { ...on, capture: true });

    const timer = host.setInterval(sync, 750);
    const runtime = {
        destroy() {
            host.clearInterval(timer);
            listeners.abort();
            unmount();
            if (host[runtimeKey] === runtime) delete host[runtimeKey];
        },
    };
    host[runtimeKey] = runtime;
    window.addEventListener('pagehide', () => runtime.destroy(), { once: true });
    sync();
})();
